/* Interactive source viewer. Reads window.SV_VIEWER_CASES (generated by
   scripts/build_viewer_bundle.py) and swaps one iframe between the five task
   viewers. The iframe is only created when the reader asks for it, so the
   article does not download the viewer libraries and task assets on load. */

(function () {
  "use strict";

  var data = window.SV_VIEWER_CASES;
  var root = document.querySelector("[data-live-viewer]");
  if (!data || !root || !data.cases || !data.cases.length) return;

  var el = {
    tabs: root.querySelector("[data-tabs]"),
    poster: root.querySelector("[data-poster]"),
    posterImg: root.querySelector("[data-poster-img]"),
    load: root.querySelector("[data-load]"),
    status: root.querySelector("[data-status]"),
    frame: root.querySelector("[data-frame]"),
    domain: root.querySelector("[data-domain]"),
    caption: root.querySelector("[data-caption]"),
    task: root.querySelector("[data-task]"),
    question: root.querySelector("[data-question]"),
    fullscreen: root.querySelector("[data-fullscreen]")
  };

  var cases = data.cases;
  var state = { index: 0, activated: false, loading: false, readyTimer: 0 };

  function current() { return cases[state.index]; }

  function setStatus(message, isError) {
    if (!message) {
      el.status.hidden = true;
      el.status.textContent = "";
      el.status.classList.remove("is-error");
      return;
    }
    el.status.hidden = false;
    el.status.textContent = message;
    el.status.classList.toggle("is-error", !!isError);
  }

  function webglAvailable() {
    try {
      var canvas = document.createElement("canvas");
      return !!(window.WebGLRenderingContext &&
        (canvas.getContext("webgl2") || canvas.getContext("webgl")));
    } catch (error) {
      return false;
    }
  }

  function renderChrome() {
    var item = current();
    el.posterImg.src = item.poster;
    el.posterImg.alt = item.posterAlt || (item.discipline + " task preview");
    el.load.textContent = "Load interactive view · " + item.size;
    el.domain.textContent = item.discipline;
    el.caption.textContent = item.caption;
    el.task.textContent = item.task + "  ·  " + item.size;
    el.question.innerHTML = item.questionHtml || "";
    el.question.scrollTop = 0;

    var tabs = el.tabs.children;
    for (var i = 0; i < tabs.length; i++) {
      tabs[i].setAttribute("aria-selected", i === state.index ? "true" : "false");
      tabs[i].tabIndex = i === state.index ? 0 : -1;
    }
  }

  function showPoster() {
    state.loading = false;
    el.poster.hidden = false;
    el.frame.hidden = true;
    el.frame.removeAttribute("src");
    el.load.hidden = false;
    setStatus("");
  }

  function reveal() {
    window.clearTimeout(state.readyTimer);
    state.loading = false;
    el.poster.hidden = true;
    el.frame.hidden = false;
    setStatus("");
  }

  function loadCurrent() {
    var item = current();
    if (!webglAvailable()) {
      setStatus("This browser cannot start WebGL, so the 3D view is unavailable. "
        + "The static preview and the recorded inspection below show the same source.",
        true);
      return;
    }

    state.activated = true;
    state.loading = true;
    el.load.hidden = true;
    // Keep the iframe in the layout while it loads; the poster sits above it.
    // A display:none iframe can initialise WebGL with a 0x0 drawing buffer.
    el.frame.hidden = false;
    el.frame.title = item.discipline + " 3D viewer: " + item.task;
    setStatus("Loading viewer…");
    el.frame.src = item.url;

    window.clearTimeout(state.readyTimer);
    var fallback = item.bytes > 10 * 1000 * 1000 ? 30000 : 12000;
    state.readyTimer = window.setTimeout(reveal, fallback);
  }

  function select(index) {
    var same = index === state.index;
    state.index = index;
    renderChrome();

    if (!state.activated) {
      showPoster();
      return;
    }

    if (same) return;
    loadCurrent();
  }

  function buildTabs() {
    cases.forEach(function (item, index) {
      var button = document.createElement("button");
      button.type = "button";
      button.className = "sv-live__tab";
      button.textContent = item.discipline;
      button.setAttribute("role", "tab");
      button.setAttribute("aria-controls", "sv-live-stage");
      button.addEventListener("click", function () { select(index); });
      button.addEventListener("keydown", function (event) {
        var next = -1;
        if (event.key === "ArrowRight") next = (index + 1) % cases.length;
        else if (event.key === "ArrowLeft") next = (index - 1 + cases.length) % cases.length;
        else if (event.key === "Home") next = 0;
        else if (event.key === "End") next = cases.length - 1;
        if (next >= 0) {
          event.preventDefault();
          select(next);
          el.tabs.children[next].focus();
        }
      });
      el.tabs.appendChild(button);
    });
  }

  function onMessage(event) {
    if (event.origin !== window.location.origin) return;
    var message = event.data;
    if (!message || message.source !== "sv-viewer") return;

    if (message.type === "ready") {
      reveal();
    } else if (message.type === "error") {
      window.clearTimeout(state.readyTimer);
      state.activated = false;
      state.loading = false;
      showPoster();
      setStatus("The viewer could not start. Use Full screen to open it in a new tab, "
        + "or check the browser console for the underlying error.", true);
    }
  }

  function openFullscreen() {
    var item = current();
    if (!state.activated) loadCurrent();

    if (!el.frame.requestFullscreen) {
      window.open(item.url, "_blank", "noopener");
      return;
    }

    try {
      var request = el.frame.requestFullscreen();
      if (request && request.catch) {
        request.catch(function () {
          window.open(item.url, "_blank", "noopener");
        });
      }
    } catch (error) {
      window.open(item.url, "_blank", "noopener");
    }
  }

  buildTabs();
  renderChrome();
  showPoster();

  el.load.addEventListener("click", loadCurrent);
  el.fullscreen.addEventListener("click", openFullscreen);
  window.addEventListener("message", onMessage);
})();
